function _wrapWithChildren(kind: string, children: readonly unknown[]): unknown {
	switch (kind) {
		case 'program':
			return (coerceToProgram as (...args: unknown[]) => unknown)(...children);
		case 'decimal_floating_point_literal':
			return F.buildDecimalFloatingPointLiteral(
				children[0] as Parameters<typeof F.buildDecimalFloatingPointLiteral>[0]
			);
		case 'hex_floating_point_literal':
			return F.buildHexFloatingPointLiteral(children[0] as Parameters<typeof F.buildHexFloatingPointLiteral>[0]);
		case 'string_interpolation':
			return F.buildStringInterpolation(children[0] as Parameters<typeof F.buildStringInterpolation>[0]);
		case 'multiline_string_literal_arm1':
			return F.buildMultilineStringLiteralArm1(children[0] as Parameters<typeof F.buildMultilineStringLiteralArm1>[0]);
		case 'inferred_parameters':
			return (coerceToInferredParameters as (...args: unknown[]) => unknown)(...children);
		case 'parenthesized_expression':
			return F.buildParenthesizedExpression(children[0] as Parameters<typeof F.buildParenthesizedExpression>[0]);
		case 'class_literal':
			return F.buildClassLiteral(children[0] as Parameters<typeof F.buildClassLiteral>[0]);
		case 'object_creation_expression':
			return F.buildObjectCreationExpression(children[0] as Parameters<typeof F.buildObjectCreationExpression>[0]);
		case 'argument_list':
			return (coerceToArgumentList as (...args: unknown[]) => unknown)(...children);
		case 'type_arguments':
			return (coerceToTypeArguments as (...args: unknown[]) => unknown)(...children);
		case 'wildcard_bounds':
			return F.buildWildcardBounds(children[0] as Parameters<typeof F.buildWildcardBounds>[0]);
		case 'dimensions':
			return (coerceToDimensions as (...args: unknown[]) => unknown)(...children);
		case 'switch_block':
			return (coerceToSwitchBlock as (...args: unknown[]) => unknown)(...children);
		case 'switch_label':
			return F.buildSwitchLabel(children[0] as Parameters<typeof F.buildSwitchLabel>[0]);
		case 'pattern':
			return F.buildPattern(children[0] as Parameters<typeof F.buildPattern>[0]);
		case 'record_pattern_body':
			return (coerceToRecordPatternBody as (...args: unknown[]) => unknown)(...children);
		case 'record_pattern_component':
			return F.buildRecordPatternComponent(children[0] as Parameters<typeof F.buildRecordPatternComponent>[0]);
		case 'guard':
			return F.buildGuard(children[0] as Parameters<typeof F.buildGuard>[0]);
		case 'block':
			return (coerceToBlock as (...args: unknown[]) => unknown)(...children);
		case 'expression_statement':
			return F.buildExpressionStatement(children[0] as Parameters<typeof F.buildExpressionStatement>[0]);
		case 'assert_statement':
			return F.buildAssertStatement(children[0] as Parameters<typeof F.buildAssertStatement>[0]);
		case 'break_statement':
			return F.buildBreakStatement(children[0] as Parameters<typeof F.buildBreakStatement>[0]);
		case 'continue_statement':
			return F.buildContinueStatement(children[0] as Parameters<typeof F.buildContinueStatement>[0]);
		case 'return_statement':
			return F.buildReturnStatement(children[0] as Parameters<typeof F.buildReturnStatement>[0]);
		case 'yield_statement':
			return F.buildYieldStatement(children[0] as Parameters<typeof F.buildYieldStatement>[0]);
		case 'throw_statement':
			return F.buildThrowStatement(children[0] as Parameters<typeof F.buildThrowStatement>[0]);
		case 'catch_type':
			return (coerceToCatchType as (...args: unknown[]) => unknown)(...children);
		case 'finally_clause':
			return F.buildFinallyClause(children[0] as Parameters<typeof F.buildFinallyClause>[0]);
		case 'resource_specification':
			return F.buildResourceSpecification(children[0] as Parameters<typeof F.buildResourceSpecification>[0]);
		case 'resource':
			return F.buildResource(children[0] as Parameters<typeof F.buildResource>[0]);
		case 'marker_annotation':
			return F.buildMarkerAnnotation(children[0] as Parameters<typeof F.buildMarkerAnnotation>[0]);
		case 'annotation_argument_list':
			return (coerceToAnnotationArgumentList as (...args: unknown[]) => unknown)(...children);
		case 'element_value_array_initializer':
			return F.buildElementValueArrayInitializer(
				children[0] as Parameters<typeof F.buildElementValueArrayInitializer>[0]
			);
		case 'module_body':
			return (coerceToModuleBody as (...args: unknown[]) => unknown)(...children);
		case 'uses_module_directive':
			return F.buildUsesModuleDirective(children[0] as Parameters<typeof F.buildUsesModuleDirective>[0]);
		case 'enum_body_declarations':
			return (coerceToEnumBodyDeclarations as (...args: unknown[]) => unknown)(...children);
		case 'modifiers':
			return (coerceToModifiers as (...args: unknown[]) => unknown)(...children);
		case 'type_parameters':
			return (coerceToTypeParameters as (...args: unknown[]) => unknown)(...children);
		case 'type_bound':
			return (coerceToTypeBound as (...args: unknown[]) => unknown)(...children);
		case 'superclass':
			return F.buildSuperclass(children[0] as Parameters<typeof F.buildSuperclass>[0]);
		case 'super_interfaces':
			return F.buildSuperInterfaces(children[0] as Parameters<typeof F.buildSuperInterfaces>[0]);
		case 'type_list':
			return (coerceToTypeList as (...args: unknown[]) => unknown)(...children);
		case 'permits':
			return F.buildPermits(children[0] as Parameters<typeof F.buildPermits>[0]);
		case 'class_body':
			return (coerceToClassBody as (...args: unknown[]) => unknown)(...children);
		case 'static_initializer':
			return F.buildStaticInitializer(children[0] as Parameters<typeof F.buildStaticInitializer>[0]);
		case 'annotation_type_body':
			return (coerceToAnnotationTypeBody as (...args: unknown[]) => unknown)(...children);
		case 'extends_interfaces':
			return F.buildExtendsInterfaces(children[0] as Parameters<typeof F.buildExtendsInterfaces>[0]);
		case 'interface_body':
			return (coerceToInterfaceBody as (...args: unknown[]) => unknown)(...children);
		case 'array_initializer':
			return F.buildArrayInitializer(children[0] as Parameters<typeof F.buildArrayInitializer>[0]);
		case 'throws':
			return (coerceToThrows as (...args: unknown[]) => unknown)(...children);
		case 'array_creation_expression_arm1':
			return (coerceToArrayCreationExpressionArm1 as (...args: unknown[]) => unknown)(...children);
		case 'resources':
			return (coerceToResources as (...args: unknown[]) => unknown)(...children);
		case 'element_values':
			return (coerceToElementValues as (...args: unknown[]) => unknown)(...children);
		case 'enum_constants':
			return (coerceToEnumConstants as (...args: unknown[]) => unknown)(...children);
		case 'variable_initializers':
			return (coerceToVariableInitializers as (...args: unknown[]) => unknown)(...children);
		case 'wildcard_bounds_arm':
			return F.buildWildcardBoundsArm(children[0] as Parameters<typeof F.buildWildcardBoundsArm>[0]);
		case 'for_statement_arm':
			return (coerceToForStatementArm as (...args: unknown[]) => unknown)(...children);
		case 'formal_parameters_receiver':
			return F.buildFormalParametersReceiver(children[0] as Parameters<typeof F.buildFormalParametersReceiver>[0]);
		case 'string_literal_line':
			return (coerceToStringLiteralLine as (...args: unknown[]) => unknown)(...children);
		case 'string_literal_text_block':
			return (coerceToStringLiteralTextBlock as (...args: unknown[]) => unknown)(...children);
		case 'type_identifier':
			return F.buildTypeIdentifier(children[0] as Parameters<typeof F.buildTypeIdentifier>[0]);
		default:
			return undefined;
	}
}

function _wrapArray<T>(kind: string, arr: readonly unknown[]): Admit<T> {
	const elementKind = _wrapElementKinds[kind];
	if (_wrapDirectKinds.has(kind) && elementKind !== undefined && elementKind in _wrapKindIds) {
		if (arr.length === 0 && _wrapOptionalSoleKinds.has(kind)) return _wrapWithChildren(kind, []) as Admit<T>;
		return _wrapWithChildren(kind, [_wrapArray(elementKind, arr)]) as Admit<T>;
	}
	return _wrapWithChildren(kind, arr) as Admit<T>;
}

function _resolveOneBranch<T>(
	v: _LooseFieldInput,
	kind: string,
	altKinds?: readonly (string | number)[],
	optionalSlot?: boolean
): Admit<T> {
	if (v === undefined || v === null) return v as Admit<T>;
	if (optionalSlot === true && Array.isArray(v) && v.length === 0) return undefined as Admit<T>;
	const tagged = _splitTag(v);
	if (tagged !== undefined) {
		const kn = _fromOfTag(tagged.tag, [kind]);
		if (kn !== kind && kind in _wrapKindIds)
			return _resolveOneBranch<T>(_resolveByKind(kn, tagged.rest), kind, altKinds);
	}
	if (isNodeValue(v)) {
		const wrapId = _wrapKindIds[kind];
		if (wrapId !== undefined && v.$type !== wrapId) {
			if (altKinds !== undefined && altKinds.some((k) => k === v.$type)) return v as Admit<T>;
			return _wrapWithChildren(kind, [v]) as Admit<T>;
		}
		return v as Admit<T>;
	}
	if (Array.isArray(v) && kind in _wrapKindIds) {
		return _wrapArray(kind, v) as Admit<T>;
	}
	if ((typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') && _isFromKind(kind)) {
		return _resolveByKind(kind, v) as Admit<T>;
	}
	if (typeof v === 'object' && !Array.isArray(v)) {
		const tagged = _splitTag(v);
		if (tagged !== undefined) return _resolveByKind(_fromOfTag(tagged.tag, [kind]), tagged.rest) as Admit<T>;
		if (_isFromKind(kind)) return _resolveByKind(kind, v) as Admit<T>;
	}
	if (typeof v === 'object' || typeof v === 'number' || typeof v === 'bigint' || typeof v === 'boolean') {
		throw new Error(`_resolveOneBranch: cannot resolve value to branch kind '${kind}': ${describeValue(v)}`);
	}
	return v as Admit<T>;
}

function _resolveManyLeaf<T>(v: _LooseFieldInput, kind: string): readonly Admit<T>[] {
	if (v === undefined || v === null) return [];
	const arr: readonly _LooseFieldInput[] = Array.isArray(v) ? v : [v];
	return arr.map((e) => _resolveOneLeaf<T>(e, kind));
}

function _resolveManyBranch<T>(
	v: _LooseFieldInput,
	kind: string,
	altKinds?: readonly (string | number)[]
): readonly Admit<T>[] {
	if (v === undefined || v === null) return [];
	const arr: readonly _LooseFieldInput[] = Array.isArray(v) ? v : [v];
	return arr.map((e) => _resolveOneBranch<T>(e, kind, altKinds));
}

function _resolveBooleanKeyword<T>(v: _LooseFieldInput): T {
	if (v === undefined || v === null) return v as T;
	if (v === true || v === false) return v as T;
	if (typeof v === 'string') return true as T;
	if (isNodeValue(v)) return v as T;
	if (Array.isArray(v)) return v as T;
	return v as T;
}

function _resolveBitflag<T>(v: _LooseFieldInput): T {
	if (v === undefined || v === null) return v as T;
	if (typeof v === 'number') return v as T;
	if (typeof v === 'string') return v as T;
	if (Array.isArray(v)) return v as T;
	if (isNodeValue(v)) return v as T;
	return v as T;
}

/** Narrows a coercer input to its config arm. A bare `isNodeValue` check
 *  cannot: the UntypedNode arm is not a strict subtype of the config arm, so
 *  negative narrowing leaves it in place. */
function _isLooseConfig<C>(v: C | AnyUntypedNode): v is C {
	return !isNodeValue(v);
}

